<?php $title=$title??'Module'; require __DIR__.'/../layouts/header.php'; ?><div class="pagehead"><h1><?=\App\Core\View::e($title)?></h1></div><div class="panel table-wrap"><table><thead><tr><?php if($rows):foreach(array_keys($rows[0]) as $h):?><th><?=\App\Core\View::e($h)?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $v):?><td><?=\App\Core\View::e(is_scalar($v)?$v:json_encode($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../layouts/footer.php';?>